import{advance,choose,random}from './engine.js';import{automaticAction,decisionUid}from './decisions.js';import{importantEvent,readingMs,TIME_CONFIG}from './time-config.js';
export const STORY_CONFIG={maxDaysPerSlice:60,storyWaitMin:1600,storyWaitMax:9000,observeWaitMin:800,observeWaitMax:4500,storyRoutineDays:7,observeRoutineDays:30,summaryDays:30};
const ORDINARY_IDS=new Set(['smell','sleep','world','play','family','street','shelter','companion-routine']);
export function ordinaryRecord(e){return !importantEvent(e)&&e.id!=='decision-outcome'&&(ORDINARY_IDS.has(e.id)||e.automatic===true&&typeof e.routineType==='string'&&(e.routineType==='dog-meet'||e.routineType.startsWith('situation:')));}
export function simulationMode(s){const c=s.chronicle;c.preferences.progressMode??='story';return c.preferences.progressMode;}
export function nextStoryBeat(s,{maxDays=STORY_CONFIG.maxDaysPerSlice,observe=simulationMode(s)==='observe'}={}){const from=s.log.length,start=s.day;let days=0;while(s.alive&&days<maxDays){if(s.pending){if(s.mode!=='observe')break;choose(s,automaticAction(s,random),decisionUid(s));s.presentation=null;if(s.log.length>from)break;}const n=s.log.length;advance(s,1);days++;if(s.pending||!s.alive)break;const added=s.log.slice(n);if(added.some(e=>importantEvent(e)||e.id==='decision-outcome'||!ordinaryRecord(e)))break;if(added.length&&days>=(observe?STORY_CONFIG.observeRoutineDays:STORY_CONFIG.storyRoutineDays))break;}
const events=s.log.slice(from);const important=events.some(importantEvent);const routine=events.filter(ordinaryRecord),significant=events.filter(e=>!ordinaryRecord(e));const summary=routine.length>1?`${start}일–${s.day}일 · ${routine.length}개의 일상 기록이 쌓였다. ${routine.at(-1).text}`:routine[0]?.text||'';const text=[summary,...significant.map(e=>e.text)].filter(Boolean).join(' ');return {from,start,end:s.day,days,events,important,text,readingText:significant.map(e=>e.text).join(' '),waitMs:Math.max(observe?STORY_CONFIG.observeWaitMin:STORY_CONFIG.storyWaitMin,Math.min(observe?STORY_CONFIG.observeWaitMax:STORY_CONFIG.storyWaitMax,readingMs(text)*(observe?.55:.8)))};}
// Summaries are presentation only; every raw event and every internal day is retained.
export function timelineEntries(s,{summarize=true}={}){const result=[],resolved=new Set(s.log.filter(e=>e.id==='decision-outcome').map(e=>e.decisionUid));let group=null;for(let i=0;i<s.log.length;i++){const e=s.log[i];if(e.id==='choice'||e.resolvedDecisionUid&&resolved.has(e.resolvedDecisionUid))continue;if(e.id==='decision'&&s.log.slice(i+1,i+8).some(r=>r.id==='decision-outcome'&&r.prompt===e.text))continue;const ordinary=ordinaryRecord(e);if(summarize&&ordinary){if(group&&e.day-group.start<=STORY_CONFIG.summaryDays&&group.area===e.area&&group.home===e.home){group.day=e.day;group.count++;group.indices.push(i);group.text=`${group.start}일–${group.day}일 · ${group.count}개의 일상 기록. ${e.text}`;continue}group={...e,index:i,start:e.day,count:1,indices:[i],summary:true};result.push(group)}else{group=null;result.push({...e,index:i})}}return result;}

export function beatDelay(beat,speed=1){const scaled=Math.max(500,beat.waitMs/(TIME_CONFIG.speeds.includes(Number(speed))?Number(speed):1));const readingText=beat.readingText??beat.text;return beat.important||readingText.length>120?Math.max(scaled,readingMs(readingText)):scaled;}
